const fs = require('fs');
const input = $input.first().json;
const body = input.body || input;
const jobId = body.job_id;

// 1. Strict job_id validation (prevent path traversal and arbitrary paths)
if (!jobId || typeof jobId !== 'string' || !/^job_[a-zA-Z0-9_-]+$/.test(jobId)) {
  throw new Error('INVALID_JOB_ID: Missing or invalid job_id in cleanup webhook payload');
}

// 2. Strict filesystem path resolution
const storageDir = '/data/jobs';
const jobDir = `${storageDir}/${jobId}`;
const audioPath = `${jobDir}/audio.webm`;

// 3. Genuine idempotent deletion using fs.unlinkSync
let wasDeleted = false;
try {
  fs.unlinkSync(audioPath);
  wasDeleted = true;
} catch (err) {
  // Idempotent: if audio.webm is already missing (ENOENT), treat as success
  if (err.code !== 'ENOENT') {
    throw err;
  }
}

return [{
  json: {
    success: true,
    job_id: jobId,
    target_audio: audioPath,
    deleted: wasDeleted,
    message: wasDeleted ? 'Temporary audio deleted successfully' : 'Temporary audio already absent (idempotent)'
  }
}];
